#!/usr/bin/env node
// blocks/catalog.mjs: generate blocks/CATALOG.md. Node port of catalog.ps1.
//
// The reference Opus reads when writing a live video's scene list: every
// archetype, its duration, and every variable it accepts (id, label, default).
// Regenerate after add-vars / any meta-header change.

import fs from "node:fs";
import path from "node:path";
import { BLOCKS, ORDER, CRLF, readMeta, write, psString } from "./_blocks.mjs";

const out = [
  "# zg-frames block catalog",
  "",
  "Auto-generated by `catalog.ps1`. One archetype per section. Mount a block in a",
  'live video with `data-composition-src="blocks/<name>/<name>.html"` and pass the',
  "variables below via `data-variable-values` on the slot. Timing comes from the",
  "`data-sent` anchor + `stamp-timing.ps1`, never a hand-typed number.",
  "",
];

for (const name of ORDER) {
  if (!fs.existsSync(path.join(BLOCKS, name, `${name}.src.html`))) continue;
  const meta = readMeta(name);
  out.push(`## ${name}`, "");
  out.push(`duration \`${psString(meta.duration)}s\` · camClass \`${psString(meta.camClass)}\`${meta.sectionEnd ? " · closes a section (signature ring)" : ""}`, "");
  if (meta.variables && meta.variables.length > 0) {
    out.push("| variable | what it is | default |", "|---|---|---|");
    for (const v of meta.variables) {
      out.push(`| \`${psString(v.id)}\` | ${psString(v.label)} | ${psString(v.default).replace(/\|/g, "\\|")} |`);
    }
  } else {
    out.push("_No variables — fixed content._");
  }
  out.push("");
}

write(path.join(BLOCKS, "CATALOG.md"), out.join(CRLF) + CRLF);
console.log(`\x1b[32mwrote CATALOG.md (${ORDER.length} archetypes)\x1b[0m`);
